#include "pvp742_guest_memory_fixture.h"
#include "ui/gen/pm_snapshot_delivery.h"
#include "sim/pvp/gen/pm_native_snapshot_worker.h"
using namespace pvz;using namespace pvz::guest_memory_audit;
struct Queue {
 std::shared_ptr<pm_network::C__BaseTransport> p=std::make_shared<pm_network::C__BaseTransport>();V v=V::inst(p);
 Queue(){pm_network::initcv__BaseTransport(p.get());p->m__init_base(Args{V::none(),SV("queue-audit"),pm_network::MAX_FRAME_BYTES,V(2),V(30),V(10),V(30)});for(const char* peer:{"a","b","c"})p->m__ready(Args{V(peer),V(true)});}
 bool send(const char* peer,const V& payload){return p->m_send(Args{V(peer),payload}).truthy();}
 V drain(){return py::iter_list(p->m__pop_commands(Args{}));}
 J metrics(){return json(p->m_statistics(Args{}));}
 void empty(){require(p->a__queued_bytes==V(0)&&p->a__peer_queued_bytes.len()==0&&p->a__snapshot_commands.len()==0,"queue accounting or coalescing index retained data");}
};
V snap(int tick,bool map=false,const char* stream="battle-1",size_t padding=0){return py_dict({{SV("type"),SV("room_snapshot")},{SV("snapshot_stream"),V::list({V(stream)})},{SV("map_included"),V(map)},{SV("tick"),V(tick)},{SV("data"),V(std::string(padding,'x'))}});}
int main(int argc,char**argv){if(argc!=2)return 2;SDL_SetMainReady();gil::init();data::set_data_dir("extract/data");pg::install_pygame();init_pvp_modules();pm_network::init();J checks=J::array();int failures=0;
 auto test=[&](const char* name,auto fn){try{J evidence=fn();checks.push_back({{"name",name},{"passed",true},{"evidence",evidence}});}catch(const std::exception&e){++failures;checks.push_back({{"name",name},{"passed",false},{"error",e.what()}});}};
 test("three_peers_bounded_latest_snapshot_and_full_map",[]{Queue q;for(const char* peer:{"a","b","c"}){require(q.send(peer,snap(0,true,"battle-1",32768)),"full snapshot rejected");for(int i=1;i<=100;++i)require(q.send(peer,snap(i,false,"battle-1",32768)),"bounded latest snapshot rejected");}
  J metrics=q.metrics();require(metrics["command_items"]==6,"obsolete snapshots retained");require(metrics["coalesced_outgoing_snapshots"]==297,"coalescing count differs");V rows=q.drain();require(rows.len()==6,"map prerequisite lost");for(int i=0;i<6;i+=2){require(rd(rows.idx(i).idx(1),SV("map_included")).truthy(),"first full map lost");require(rd(rows.idx(i+1).idx(1),SV("tick"))==V(100),"latest tick not retained");}q.empty();return metrics;});
 test("input_and_other_message_ordering_barriers",[]{Queue q;V command=py_dict({{SV("type"),SV("room_command")},{SV("input"),SV("jump")}});require(q.send("a",snap(1))&&q.send("a",command)&&q.send("a",snap(2))&&q.send("a",snap(3)),"admission failed");V rows=q.drain();require(rows.len()==3,"command barrier crossed");require(rd(rows.idx(0).idx(1),SV("tick"))==V(1)&&rows.idx(1).idx(1)==command&&rd(rows.idx(2).idx(1),SV("tick"))==V(3),"ordered messages differ");q.empty();return json(rows);});
 test("map_phase_and_stream_transitions",[]{Queue q;for(const V& s:{snap(1),snap(2,true),snap(3),snap(4,false,"battle-2"),snap(5,false,"battle-2")})require(q.send("a",s),"send failed");V rows=q.drain();require(rows.len()==3,"map/stream barrier count differs");require(rd(rows.idx(0).idx(1),SV("tick"))==V(2)&&rd(rows.idx(0).idx(1),SV("map_included")).truthy()&&rd(rows.idx(1).idx(1),SV("tick"))==V(3)&&rd(rows.idx(2).idx(1),SV("tick"))==V(5),"map or stream barrier lost");q.empty();return json(rows);});
 test("reconnect_never_replaces_old_generation",[]{Queue q;require(q.send("a",snap(1)),"old send failed");q.p->m__ready(Args{V("a"),V(false)});q.p->m__ready(Args{V("a"),V(true)});require(q.send("a",snap(2)),"new send failed");V rows=q.drain();require(rows.len()==1&&rd(rows.idx(0).idx(1),SV("tick"))==V(2),"old generation leaked or new discarded");q.empty();return json(rows);});
 test("caller_mutation_cannot_change_frozen_payload_or_stream",[]{Queue q;V payload=snap(1);require(q.send("a",payload),"send failed");setitem(payload,SV("tick"),V(999));setitem(rd(payload,SV("snapshot_stream")),V(0),V("changed"));require(q.send("a",snap(2)),"replacement failed");V rows=q.drain();require(rows.len()==1&&rd(rows.idx(0).idx(1),SV("tick"))==V(2),"caller mutation altered stream identity");q.empty();return json(rows);});
 test("ordinary_commands_keep_capacity_and_exact_order",[]{Queue q;for(int i=0;i<256;++i)require(q.send("a",py_dict({{SV("type"),SV("room_command")},{SV("seq"),V(i)}})),"ordinary command rejected below cap");const J before=q.metrics();require(!q.send("a",snap(7)),"queue item cap exceeded");require(q.metrics()["queued_command_bytes"]==before["queued_command_bytes"],"failed admission changed bytes");int count=0;while(count<256){V rows=q.drain();require(rows.len()>0,"queue stopped early");for(const V& row:rows.items())require(rd(row.idx(1),SV("seq"))==V(count++),"input lost/reordered");}q.empty();return before;});
 test("discard_releases_latest_payload_and_peer_index",[]{Queue q;for(int i=0;i<50;++i)require(q.send("b",snap(i,false,"battle-1",65536)),"snapshot refused");J metrics=q.metrics();q.p->m__discard_commands(Args{});q.empty();return metrics;});
 test("blocked_wire_defers_encoding_without_blocking_other_peer",[]{Queue q;V conn=pm_network::new__Connection(Args{V::none(),pm_network::MAX_FRAME_BYTES});setattr(conn,SY("ready"),V(true));setattr(conn,SY("peer_id"),V("a"));callm(getattr(conn,SY("output")),SY("extend"),Args{V::bytes("partial-frame")});setattr(q.v,SY("_connections"),py_dict({{V("socket"),conn}}));
  require(q.send("a",snap(1))&&q.send("b",snap(2))&&q.send("a",snap(3)),"admission failed");V fast=q.drain();require(fast.len()==1&&fast.idx(0).idx(0)==V("b"),"blocked peer held unrelated peer or wrote stale state");require(q.drain().len()==0,"blocked queue did not remain bounded");require(q.send("a",snap(4)),"latest snapshot replacement failed");
  callm(getattr(conn,SY("output")),SY("clear"),Args{});V slow=q.drain();require(slow.len()==1&&rd(slow.idx(0).idx(1),SV("tick"))==V(4),"wire recovery did not send newest state");q.empty();return q.metrics();});
 test("delivery_cancel_and_generation_invalidate_pending_pack",[]{Queue q;V worker=pm_native_snapshot_worker::new_SnapshotPackWorker(Args{SV("thread")});V stamp=V::tuple({V::tuple({V("map"),V(1)}),V("battle"),V(1),V("load")});V ticket=pm_snapshot_delivery::new_SnapshotDelivery(Args{q.v,V("a"),stamp,V(true)});
  callm(ticket,SY("cancel"),Args{});require(callm(worker,SY("submit"),Args({V("a"),V(1),py_dict({{V("tick"),V(1)}})},{{SY("delivery"),ticket}})).truthy(),"submit failed");
  auto start=std::chrono::steady_clock::now();while(callm(worker,SY("completed"),Args{}).len()==0){{gil::Release release;std::this_thread::sleep_for(std::chrono::milliseconds(1));}require(std::chrono::steady_clock::now()-start<std::chrono::seconds(5),"cancelled pack did not finish");}
  require(!callm(ticket,SY("accepted"),Args{}).truthy()&&q.drain().len()==0,"cancelled ticket sent");
  V old=pm_snapshot_delivery::new_SnapshotDelivery(Args{q.v,V("a"),stamp,V(true)});q.p->m__ready(Args{V("a"),V(false)});q.p->m__ready(Args{V("a"),V(true)});callm(old,SY("publish"),Args{snap(9)});require(!callm(old,SY("accepted"),Args{}).truthy()&&q.drain().len()==0,"old ticket crossed reconnect");callm(worker,SY("close"),Args{});q.empty();return J{{"cancelled_sent",false},{"stale_generation_sent",false}};});
 J report={{"passed",failures==0},{"total",checks.size()},{"failures",failures},{"checks",checks}};std::ofstream(argv[1],std::ios::binary)<<report.dump(2);std::cout<<report.dump()<<'\n';return failures?1:0;
}
